import './Chip.css';

const isOn = (value) => value === true || value === 'True';

export function Chip({
  Size = 'M',
  Icon = 'False',
  Label = 'Filter',
  pressed = false,
  onPressedChange,
  className,
  ...rest
}) {
  const classes = ['chip', Size === 'L' && 'chip--l', className].filter(Boolean).join(' ');
  return (
    <button
      type="button"
      className={classes}
      aria-pressed={pressed ? 'true' : 'false'}
      onClick={() => onPressedChange?.(!pressed)}
      {...rest}
    >
      {isOn(Icon) && <span className="chip__icon" aria-hidden="true" />}
      {Label}
    </button>
  );
}

export default Chip;

