import { useId } from "react";
import "./Field.css";

/**
 * field — a one-line text input (Figma node 3:21).
 * State: "Default" | "Error" (Figma's variant). Give it a `label` (used as its aria-label)
 * or pass aria-label / aria-labelledby yourself. While State is "Error", `errorMessage`
 * is shown and linked to the input with aria-describedby.
 */
export function Field({ State = "Default", label, errorMessage, className, id, ...rest }) {
  const autoId = useId();
  const inputId = id ?? autoId;
  const isError = State === "Error";
  const messageId = isError && errorMessage ? `${inputId}-error` : undefined;
  const classes = ["field", isError && "field--error", className].filter(Boolean).join(" ");

  return (
    <>
      <input
        type="text"
        id={inputId}
        className={classes}
        aria-label={label}
        aria-invalid={isError ? "true" : undefined}
        aria-describedby={messageId}
        {...rest}
      />
      {messageId && <span id={messageId}>{errorMessage}</span>}
    </>
  );
}

export default Field;

